export const STRINGS = { "English": EN, "Nigerian Pidgin": PCM, "Hausa": HA, "Yoruba": YO, "Igbo": IG };

export function translate(lang, key, vars = {}) {
  const s = STRINGS[lang]?.[key] ?? EN[key] ?? key;
  return s.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? vars[k] : m));
}
